/* -------------------------------------------------- 纯解析函数 */

// ctx: { industry, serverMap, lang }
function getTerms(ctx) {
  const industry = (ctx && ctx.industry) || 'education';
  const base = TERM_DICT[industry] || TERM_DICT.education;
  if (!ctx || !ctx.serverMap) return base;
  return Object.assign({}, base, ctx.serverMap);
}

function termText(key, ctx) {
  if (!key) return '';
  const terms = getTerms(ctx);
  if (terms[key] != null && terms[key] !== '') return terms[key];
  if (TERM_DICT.education[key] != null) return TERM_DICT.education[key];
  return String(key);
}

function getOptions(tagKey, fallbackOptions, ctx) {
  const terms = getTerms(ctx);
  return (fallbackOptions || []).map(o => {
    const key = tagKey + '.' + (o.code != null ? o.code : o.value);
    return { value: o.value, text: (terms[key] != null && terms[key] !== '') ? terms[key] : (o.defaultText || o.value) };
  });
}

function normalizeCourseType(code) {
  if (code === null || code === undefined) return '';
  const s = String(code).trim();
  if (!s) return '';
  const low = s.toLowerCase();
  return COURSE_TYPE_ALIAS[low] || COURSE_TYPE_ALIAS[s] || low;
}

function courseTypeText(code, ctx) {
  const s = (code === null || code === undefined) ? '' : String(code).trim();
  if (!s) return '';
  const c = normalizeCourseType(s);
  const opt = COURSE_TYPE_OPTIONS.find(o => o.value === c);
  if (!opt) return s;
  return termText(opt.termKey, ctx);
}

function enumTermText(prefix, code, ctx) {
  const s = (code === null || code === undefined) ? '' : String(code).trim();
  if (!s) return '';
  const t = getTerms(ctx)[prefix + s];
  return (t != null && t !== '') ? t : s;
}

// shared/domain/refundRule.js
// 跨端共享「退改规则」领域层（纯逻辑，零 DOM / 零运行时 API 依赖）。
//
// 这是 P1（Headless 领域层下沉）的一部分：把原本混在 frontend/js/admin-refund-rule.js
// 里的分钟换算、三档判定、区间文案、规则校验、生效规则解析抽出来，让 Web 与小程
// 序共用同一份算法，UI 各自渲染。
//
// 生效顺序（业务语义）：课程专属规则 ＞ 租户默认规则 ＞ 系统内置兜底。
// 只有两个时间阈值，不退费区由「不足部分退费线」推导：
//   提前 ≥ 免责线              → 免责（退 100%）
//   部分退费线 ≤ 提前 < 免责线 → 部分退费（退 partialRefundPercent%）
//   提前 < 部分退费线          → 不退费（退 0%）
//
// 消费方式：
//   - 小程序端：import { evaluateRefund } from '../../shared/domain/refundRule.js'
//   - Web 端：经 P0 构建桥接挂到 window.RefundRuleDomain（见 PRD）
//   - Node 端：直接 require/import 做单测（本文件无任何 document/window/fetch 引用）

/* -------------------------------------------------- 内置兜底常量 */

// 系统内置默认：提前 24 小时免责 / 提前 12 小时退 50%
const REFUND_BUILT_IN_FALLBACK = Object.freeze({
  freeBeforeMinutes: 24 * 60,
  partialBeforeMinutes: 12 * 60,
  partialRefundPercent: 50,
  enabled: 1
});

/* -------------------------------------------------- 分钟 ↔ 粒度换算 */

/** 分钟数转可读文案：390 → "6 小时 30 分钟"；1440 → "24 小时"；1500 → "1 天 1 小时" */
function formatRefundMinutes(minutes) {
  if (minutes === null || minutes === undefined || minutes === '') return '-';
  const m = Number(minutes);
  if (isNaN(m)) return '-';
  if (m <= 0) return '0 分钟';
  const days = Math.floor(m / 1440);
  const rest = m % 1440;
  const hours = Math.floor(rest / 60);
  const mins = rest % 60;
  const parts = [];
  if (days > 0) parts.push(days + ' 天');
  if (hours > 0) parts.push(hours + ' 小时');
  if (mins > 0) parts.push(mins + ' 分钟');
  return parts.length ? parts.join(' ') : '0 分钟';
}

/** 按粒度把界面上的数值换算成分钟（hour→×60，minute→本身） */
function refundRuleToMinutes(value, unit) {
  const v = Number(value);
  if (isNaN(v) || v < 0) return NaN;
  return unit === 'minute' ? Math.round(v) : Math.round(v * 60);
}

/**
 * 分钟数回显成「数值 + 粒度」。
 * 优先沿用库里存的粒度；若按该粒度不能整除（如 90 分钟按小时就是 1.5），
 * 则退化为分钟显示，避免界面上出现 1.5 小时这种别扭的中间值。
 */
function refundRuleFromMinutes(minutes, unit) {
  const m = Number(minutes);
  if (isNaN(m) || m < 0) return { value: '', unit: unit || 'hour' };
  if (unit === 'minute') return { value: m, unit: 'minute' };
  if (m % 60 === 0) return { value: m / 60, unit: 'hour' };
  return { value: m, unit: 'minute' };
}

/* -------------------------------------------------- 三档区间文案 / 校验 */

/** 三档区间说明（纯前端拼，用于表单实时预览） */
function refundRuleZoneText(freeMinutes, partialMinutes, percent) {
  if (isNaN(freeMinutes) || isNaN(partialMinutes)) return '请先填写两个时间点';
  if (freeMinutes < partialMinutes) return '⚠ 免责时间点必须 ≥ 部分退费时间点';
  return '提前 ≥ ' + formatRefundMinutes(freeMinutes) + ' 免责（退 100%）　｜　'
    + formatRefundMinutes(partialMinutes) + ' ≤ 提前 < ' + formatRefundMinutes(freeMinutes)
    + ' 部分退费（退 ' + (percent === '' || isNaN(percent) ? '-' : percent) + '%）　｜　'
    + '提前 < ' + formatRefundMinutes(partialMinutes) + ' 不退费（退 0%）';
}

/**
 * 规则校验：返回 null 表示合法，否则返回错误文案（与 admin-refund-rule.js collectRefundRuleForm 的前端预校验保持一致）。
 * @param {number} freeMinutes       免责时间点（分钟）
 * @param {number} partialMinutes    部分退费时间点（分钟）
 * @param {number} percent           部分退费比例（%）
 */
function validateRefundRule(freeMinutes, partialMinutes, percent) {
  if (isNaN(freeMinutes) || freeMinutes === '') return '请填写免责时间点';
  if (isNaN(partialMinutes) || partialMinutes === '') return '请填写部分退费时间点';
  if (freeMinutes < partialMinutes) return '免责时间点必须大于或等于部分退费时间点';
  if (isNaN(percent) || percent < 1 || percent > 99) return '部分退费比例需在 1~99 之间';
  return null;
}

/* -------------------------------------------------- 生效规则解析 */

/**
 * 生效顺序解析：课程专属规则 ＞ 租户默认规则 ＞ 系统内置兜底。
 * 约定：有 id（非 null/undefined）视为「已保存的规则」；id 缺失视为「虚拟兜底项」不生效。
 * @param {Object|null} courseRule         课程专属规则（courseId 非空）
 * @param {Object|null} tenantDefaultRule  租户默认规则（courseId 为空串）
 * @returns {Object} 实际生效的规则对象
 */
function resolveEffectiveRule(courseRule, tenantDefaultRule) {
  if (courseRule && courseRule.id != null) return courseRule;
  if (tenantDefaultRule && tenantDefaultRule.id != null) return tenantDefaultRule;
  return REFUND_BUILT_IN_FALLBACK;
}

/* -------------------------------------------------- 核心：三档判定 */

/**
 * 计算某课次在给定时刻的退改档位（纯函数，零 DOM）。
 * 时间基准 = 课次的上课时间（appointmentTime）与操作时刻（now）的差值（提前多久）。
 *
 * @param {Object} rule 规则对象 { freeBeforeMinutes, partialBeforeMinutes, partialRefundPercent }
 * @param {Date|string|number} appointmentTime 课次上课时间（Date / ISO 字符串 / 时间戳）
 * @param {Date|string|number} [now]            操作时刻（默认 new Date()）
 * @returns {{ aheadMinutes:number, level:string, percent:number, levelText:string, aheadText:string }}
 *          level: 'free' 免责 | 'partial' 部分退费 | 'none' 不退费 | 'past' 已过期
 */
function evaluateRefund(rule, appointmentTime, now) {
  const appt = toDate(appointmentTime);
  const t = now == null ? new Date() : toDate(now);
  const aheadMinutes = Math.floor((appt.getTime() - t.getTime()) / 60000);

  let level, percent, levelText;
  if (aheadMinutes < 0) {
    level = 'past'; percent = 0; levelText = '已过期';
  } else if (aheadMinutes >= Number(rule.freeBeforeMinutes)) {
    level = 'free'; percent = 100; levelText = '免责';
  } else if (aheadMinutes >= Number(rule.partialBeforeMinutes)) {
    level = 'partial'; percent = Number(rule.partialRefundPercent); levelText = '部分退费';
  } else {
    level = 'none'; percent = 0; levelText = '不退费';
  }

  return {
    aheadMinutes,
    level,
    percent,
    levelText,
    aheadText: aheadMinutes < 0 ? '已过期' : formatRefundMinutes(aheadMinutes)
  };
}

/* -------------------------------------------------- 内部工具 */

function toDate(x) {
  if (x instanceof Date) return x;
  if (typeof x === 'number') return new Date(x);
  if (typeof x === 'string') {
    // 兼容 "2026-10-01 10:00"（后端部分接口用空格分隔）与标准 ISO "2026-10-01T10:00"
    const s = x.includes('T') || x.includes('Z') || x.includes('+') ? x : x.replace(' ', 'T');
    return new Date(s);
  }
  return new Date(x);
}

// shared/domain/bookingState.js
// 跨端共享「预约/排期状态机 + 候补满额判定」领域层（纯逻辑，零 DOM / 零运行时 API 依赖）。
//
// 这是 P1（Headless 领域层下沉）的一部分：把原本散落在
//   - frontend/js/public/courseAndBooking.js 的 bookingOccupiesSeat() / checkStatus_booking()
//   - frontend/js/student-bookingCards.js 的 formatRemainingSites() / FULLY_BOOKED_TEXT
//   - miniprogram/package-teacher/booking/booking.js 的 bkStatusText()
// 里的重复实现收口成唯一权威源，让 Web 与小程序共用同一套状态语义、占用口径、满额判定。
// UI 各自渲染（Decision 3：视图层允许不一致）。
//
// 【与后端同步】单一事实来源是 api/.../common/BookingStatus.java。
//   占席位态：booking(待确认) / booked(已确认) / canceling|canceling(取消申请在管理员确认前原预订仍有效)
//   非占位态：waiting(候补) / cancelled|canceled / rej-booking(预订被拒) / frozen|deleted(冻结/删除)
//   终态：    completed
//   后端存在美式/英式拼写（canceling/cancelling、canceled/cancelled），本模块统一归一。
//   并发安全（候补转正、取消）由后端闸门 857a233（排期行锁 + 锁定读计数 + CAS）保证，前端只做入口校验。
//
// 消费方式：
//   - 小程序端：import { bookingStatusText, bookingOccupiesSeat, formatRemainingSites } from '../../shared/domain/bookingState.js'
//   - Web 端：经 P0 构建桥接挂到 window.BookingStateDomain（TODO，属 P0-Web 范围）
//   - Node 端：直接 import 做单测（本文件无任何 document/window/fetch 引用）


/* -------------------------------------------------- 状态枚举（补全后端已知态） */

// 在 shared/constants.js 的 BOOKING_STATUS 基础上补全所有已知后端态，
// 避免两端各写一套 switch。BOOKING_STATUS 仍是「核心四态」入口。
const BOOKING_STATUS_ALL = Object.freeze({
  ...BOOKING_STATUS,
  PENDING: 'booking',                 // 待确认（预订提交未审核）
  COMPLETED: 'completed',             // 已完成
  REJECTED_BOOKING: 'rej-booking',    // 预订被拒
  REJECTED_CANCEL: 'rej-cancelling',  // 取消被拒
  FROZEN: 'frozen',                   // 已冻结
  DELETED: 'deleted'                  // 已删除
});

// 非占位态集合（单一事实来源，与后端 BookingStatus.NON_OCCUPYING 对齐）。
// 候补(waiting) 不占席位；取消/拒/冻结 也不再占席位。
const NON_OCCUPYING_STATUSES = Object.freeze([
  'waiting', 'cancelled', 'canceled', 'rej-booking', 'frozen', 'deleted'
]);

/* -------------------------------------------------- 状态归一 */

/**
 * 归一化状态：美式/英式拼写统一 + 空值兜底。
 * @param {string|null|undefined} status
 * @returns {string} 归一后的状态串；null/空按 DB 列 NOT NULL DEFAULT 'booked' 兜回 'booked'。
 */
function normalizeBookingStatus(status) {
  if (status === null || status === undefined) return 'booked';
  const s = String(status).trim();
  if (s === '') return 'booked';
  if (s === 'cancelling') return 'canceling';
  if (s === 'canceled') return 'cancelled';
  return s;
}

/* -------------------------------------------------- 占用 / 占位判定 */

/** 该 booking 状态是否占用一个排期席位（纯函数，零 DOM）。 */
function bookingOccupiesSeat(status) {
  return NON_OCCUPYING_STATUSES.indexOf(normalizeBookingStatus(status)) === -1;
}

/** 是否非占位（候补/取消/拒/冻结/删除） */
function isNonOccupying(status) {
  return !bookingOccupiesSeat(status);
}

/* -------------------------------------------------- 单态布尔判定（归一后比较） */

function isWaiting(status) { return normalizeBookingStatus(status) === 'waiting'; }
function isBooked(status) { return normalizeBookingStatus(status) === 'booked'; }
function isPending(status) { return normalizeBookingStatus(status) === 'booking'; }
function isCancelled(status) { return ['cancelled', 'canceled'].indexOf(normalizeBookingStatus(status)) !== -1; }
function isCompleted(status) { return normalizeBookingStatus(status) === 'completed'; }

/* -------------------------------------------------- 转移动作守卫（纯函数） */

/**
 * 是否可「确认」：候补或待确认 → 已确认。
 * 仅做入口校验；真正转正与并发由后端闸门保证。
 */
function canConfirm(status) {
  const s = normalizeBookingStatus(status);
  return s === 'waiting' || s === 'booking';
}

/** 是否可「取消」：已确认或取消待确认 → 已取消 */
function canCancel(status) {
  const s = normalizeBookingStatus(status);
  return s === 'booked' || s === 'canceling';
}

/** 是否可「拒绝」：待确认 / 候补 / 取消待确认 都可被拒 */
function canReject(status) {
  const s = normalizeBookingStatus(status);
  return s === 'waiting' || s === 'booking' || s === 'canceling';
}

/* -------------------------------------------------- 状态 → 展示文案（单一来源） */

/**
 * 状态 → 中文展示文案。两端统一语义：
 *   待确认 / 候补 / 取消待确认 / 已确认 / 已取消 / 已完成 / 已拒绝 / 已拒绝取消 / 已失效
 * 以 Web 端 checkStatus_booking 的语义为基准（最完整），覆盖 mp bkStatusText 全部分支。
 */
function bookingStatusText(status) {
  switch (normalizeBookingStatus(status)) {
    case 'booking': return '待确认';
    case 'waiting': return '候补';
    case 'canceling': return '取消待确认';
    case 'booked': return '已确认';
    case 'cancelled': return '已取消';
    case 'completed': return '已完成';
    case 'rej-booking': return '已拒绝';
    case 'rej-cancelling': return '已拒绝取消';
    case 'frozen':
    case 'deleted': return '已失效';
    default: return status || '—';
  }
}

/* -------------------------------------------------- 候补 / 满额判定（纯逻辑） */

// 满额展示文案（与 student-bookingCards.js 的 FULLY_BOOKED_TEXT 对齐，单一来源）。
const FULLY_BOOKED_TEXT = '满额';

/**
 * 剩余员额 → 展示文案（零 DOM 纯函数）。
 * ''/null/undefined/非有限数 一律按「未知」返回空串（不伪装成 0）。
 * 剩余 <= 0 → '满额'；其余显示数字。
 * 注意：满额文案绝不能当数值传给 Number()（会得到 NaN → 误判未满），
 *       需要回读数值时请用 isSiteFull / 数值载体，见 student-bookingCards.js 的 data-remaining 约定。
 */
function formatRemainingSites(remainingSites) {
  if (remainingSites === null || remainingSites === undefined || remainingSites === '') return '';
  const n = Number(remainingSites);
  if (!Number.isFinite(n)) return '';
  return n > 0 ? String(n) : FULLY_BOOKED_TEXT;
}

/** 是否满额（剩余 <= 0）；未知值不视为满（返回 false）。 */
function isSiteFull(remainingSites) {
  const n = Number(remainingSites);
  if (!Number.isFinite(n)) return false;
  return n <= 0;
}

